function u(e){if(!e)return null;let t;if(typeof e=="string")if(e.includes("/")){const s=e.split("/");if(s.length===3){const a=parseInt(s[0],10),i=parseInt(s[1],10),o=parseInt(s[2],10);t=new Date(o,i-1,a)}else t=new Date(e)}else/^\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}$/.test(e)?t=new Date(e.replace(" ","T")+"Z"):t=new Date(e);else typeof e=="number"?t=new Date(e):t=e;if(!(t instanceof Date)||isNaN(t.getTime()))return null;const n=t.getTime()+t.getTimezoneOffset()*6e4;return new Date(n+7*36e5)}function c(e,t=!1){if(!e)return"";const n=u(e);if(!n||isNaN(n.getTime()))return"";const r=String(n.getDate()).padStart(2,"0"),s=String(n.getMonth()+1).padStart(2,"0"),a=n.getFullYear();if(t){const i=String(n.getHours()).padStart(2,"0"),o=String(n.getMinutes()).padStart(2,"0");return`${r}/${s}/${a} ${i}:${o}`}return`${r}/${s}/${a}`}function f(e){if(!e)return null;const t=e.trim().split("/");if(t.length!==3)return null;const n=parseInt(t[0],10),r=parseInt(t[1],10),s=parseInt(t[2],10);if(isNaN(n)||isNaN(r)||isNaN(s)||n<1||n>31||r<1||r>12||s<1900||s>2100)return null;const a=new Date(Date.UTC(s,r-1,n,0,0,0));return new Date(a.getTime()-7*36e5)}function g(e){if(!e)return"";const t=u(e);if(!t||isNaN(t.getTime()))return"";const n=String(t.getHours()).padStart(2,"0"),r=String(t.getMinutes()).padStart(2,"0");return`${n}:${r}`}function l(e=!1){const t=new Date,n=t.getTime()+t.getTimezoneOffset()*6e4,r=new Date(n+7*36e5);if(e){const s=r.getFullYear(),a=String(r.getMonth()+1).padStart(2,"0"),i=String(r.getDate()).padStart(2,"0");return`${s}-${a}-${i}`}return r}export{g as a,c as f,l as g,f as p};
